import{_ as p,c as o,a2 as e,o as a}from"./chunks/framework.CqbvlPrP.js";const c=JSON.parse('{"title":"第一千二百二十八章 愤怒品 增支部2集181经到190经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1228第一千二百二十八章 愤怒品 增支部2集181经到190经.md","filePath":"meditation/巴利文大藏经/1228第一千二百二十八章 愤怒品 增支部2集181经到190经.md"}'),_={name:"meditation/巴利文大藏经/1228第一千二百二十八章 愤怒品 增支部2集181经到190经.md"};function u(r,t,n,q,i,s){return a(),o("div",null,t[0]||(t[0]=[e('<h1 id="第一千二百二十八章-愤怒品-增支部2集181经到190经" tabindex="-1">第一千二百二十八章 愤怒品 增支部2集181经到190经 <a class="header-anchor" href="#第一千二百二十八章-愤怒品-增支部2集181经到190经" aria-label="Permalink to &quot;第一千二百二十八章 愤怒品 增支部2集181经到190经&quot;">​</a></h1><p>完全读懂巴利文大藏经 增支部2集181经到190经</p><p>181经</p><p>&quot;比丘们，有两种法。是哪两种？愤怒和怨恨、傲慢和轻蔑、嫉妒和吝啬、虚伪和欺诈、无惭和无愧。比丘们，这就是两种法。&quot;</p><p>182经</p><p>&quot;比丘们，有两种法。是哪两种？不愤怒和不怨恨、不傲慢和不轻蔑、不嫉妒和不吝啬、不虚伪和不欺诈、有惭和有愧。比丘们，这就是两种法。&quot;</p><p>183经</p><p>&quot;比丘们，具足两法者住于痛苦。是哪两法？愤怒和怨恨、傲慢和轻蔑、嫉妒和吝啬、虚伪和欺诈、无惭和无愧。比丘们，具足这两法者住于痛苦。&quot;</p><p>184经</p><p>&quot;比丘们，具足两法者住于安乐。是哪两法？不愤怒和不怨恨、不傲慢和不轻蔑、不嫉妒和不吝啬、不虚伪和不欺诈、有惭和有愧。比丘们，具足这两法者住于安乐。&quot;</p><p>185经</p><p>&quot;比丘们，这两法会导致有学比丘退转。是哪两法？愤怒和怨恨、傲慢和轻蔑、嫉妒和吝啬、虚伪和欺诈、无惭和无愧。比丘们，这两法会导致有学比丘退转。&quot;</p><p>186</p><p>&quot;比丘们，这两法会导致有学比丘不退转。是哪两法？不愤怒和不怨恨、不傲慢和不轻蔑、不嫉妒和不吝啬、不虚伪和不欺诈、有惭和有愧。比丘们，这两法会导致有学比丘不退转。&quot;</p><p>187经</p><p>&quot;比丘们，具足两法者必定堕入地狱。是哪两法？愤怒和怨恨、傲慢和轻蔑、嫉妒和吝啬、虚伪和欺诈、无惭和无愧。比丘们，具足这两法者必定堕入地狱。&quot;</p><p>188</p><p>&quot;比丘们，具足两法者必定生天。是哪两法？不愤怒和不怨恨、不傲慢和不轻蔑、不嫉妒和不吝啬、不虚伪和不欺诈、有惭和有愧。比丘们，具足这两法者必定生天。&quot;</p><p>189经</p><p>&quot;比丘们，具足两法者，身坏命终后必堕恶趣、恶道、地狱。是哪两法？愤怒和怨恨、傲慢和轻蔑、嫉妒和吝啬、虚伪和欺诈、无惭和无愧。比丘们，具足这两法者，身坏命终后必堕恶趣、恶道、地狱。&quot;</p><p>190经</p><p>&quot;比丘们，具足两法者，身坏命终后必生善趣、天界。是哪两法？不愤怒和不怨恨、不傲慢和不轻蔑、不嫉妒和不吝啬、不虚伪和不欺诈、有惭和有愧。比丘们，具足这两法者，身坏命终后必生善趣、天界。&quot;</p><p>愤怒品完。</p>',23)]))}const l=p(_,[["render",u]]);export{c as __pageData,l as default};
